window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5968492c82422fcc"]={"versions": [{"id": "FIG-5968492c82422fcc", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Include-Abhängigkeitsdiagramm zur Darstellung der Datei- und Header-Struktur des AUTOSAR Classic BSW-Moduls XCP. Es modelliert die statischen Inklusionsbeziehungen (<code>includes</code>) zwischen den C-Quelldateien (<code>Xcp.c</code>), den modulspezifischen Headerdateien (<code>Xcp.h</code>, <code>SchM_Xcp.h</code>, busspezifischen Transport- und Callback-Headern) sowie Schnittstellenheadern benachbarter Basissoftware-Module, des Betriebssystems und allgemeiner Typdefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Quell- und Header-Dateien des Moduls:</p>\n<ul class=\"fig-list\">\n<li><code>Xcp.c</code> (Quelldatei, mehrfach geschichtet dargestellt zur Repräsentation mehrerer Übersetzungseinheiten bzw. Instanzen)</li>\n<li><code>Xcp.h</code> (Haupt-Header des XCP-Moduls)</li>\n<li><code>SchM_Xcp.h</code> (Schedule Manager Header für XCP)</li>\n<li>Modulspezifische Transport-Layer- und Callback-Header: <code>XcpOnCan.h</code>, <code>XcpOnCan_Cbk.h</code>, <code>XcpOnEth.h</code>, <code>XcpOnEth_Cbk.h</code>, <code>XcpOnFr.h</code>, <code>XcpOnFr_Cbk.h</code></li>\n</ul>\n<p class=\"fig-p\">Integrierte BSW-, System- und Schnittstellen-Header:</p>\n<ul class=\"fig-list\">\n<li><code>CanIf.h</code> (CAN Interface)</li>\n<li><code>FrIf.h</code> (FlexRay Interface)</li>\n<li><code>SoAd.h</code> (Socket Adapter)</li>\n<li><code>Dem.h</code> (Diagnostic Event Manager)</li>\n<li><code>DemIntErrId.h</code> (Dem Internal Error IDs, eingebunden durch <code>Dem.h</code>)</li>\n<li><code>Det.h</code> (Default Error Tracer)</li>\n<li><code>RTE.h</code> (Runtime Environment Header)</li>\n<li><code>StbM.h</code> (Synchronized Time-Base Manager)</li>\n<li><code>Cpu.h</code> (Hardware-/CPU-spezifische Typen)</li>\n<li><code>Os.h</code> (Betriebssystem)</li>\n<li><code>MemMap.h</code> (Speicher-Mapping-Header, separat referenziert durch <code>Xcp.c</code> und <code>Xcp.h</code>)</li>\n<li><code>ComStack_Types.h</code> (Kommunikationsstapel-Basisdatentypen)</li>\n<li><code>Std_Types.h</code> (AUTOSAR Standarddatentypen, eingebunden über <code>ComStack_Types.h</code>)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenbeziehungen (gerichtete Pfeile mit der Semantik <code>includes</code>):</p>\n<ul class=\"fig-list\">\n<li><code>Xcp.c</code> bindet ein: <code>Xcp.h</code>, <code>SchM_Xcp.h</code>, <code>CanIf.h</code>, <code>FrIf.h</code>, <code>SoAd.h</code>, <code>Dem.h</code>, <code>Det.h</code>, <code>RTE.h</code>, <code>StbM.h</code>, <code>Cpu.h</code>, <code>Os.h</code>, <code>MemMap.h</code>.</li>\n<li><code>Xcp.h</code> bindet ein: <code>ComStack_Types.h</code>, <code>MemMap.h</code>, <code>XcpOnCan.h</code>, <code>XcpOnCan_Cbk.h</code>, <code>XcpOnEth.h</code>, <code>XcpOnEth_Cbk.h</code>, <code>XcpOnFr.h</code>, <code>XcpOnFr_Cbk.h</code>.</li>\n<li><code>Dem.h</code> bindet ein: <code>DemIntErrId.h</code>.</li>\n<li><code>ComStack_Types.h</code> bindet ein: <code>Std_Types.h</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert statische Kompilierzeit- und Präprozessor-Abhängigkeiten. Es beschreibt keinen dynamischen Kontrollfluss oder Laufzeitsequenzen, sondern definiert die transitiven und direkten Sichtbarkeiten von Typen, Makros, API-Deklarationen und Speicherkonfigurationen während des Übersetzungsvorgangs.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die Modulstruktur und <code>#include</code>-Hierarchie der XCP-Implementierung in AUTOSAR Classic:</p>\n<ul class=\"fig-list\">\n<li><code>Xcp.h</code> exportiert die Modulschnittstelle und stellt alle transportspezifischen Definitionen (<code>XcpOnCan<em>.h</code>, <code>XcpOnEth</em>.h</code>, <code>XcpOnFr*.h</code>) sowie <code>ComStack_Types.h</code> (und transitiv <code>Std_Types.h</code>) bereit.</li>\n<li><code>Xcp.c</code> realisiert die eigentliche Modulfunktionalität und greift direkt auf die Schnittstellen der Bus-Interfaces (<code>CanIf</code>, <code>FrIf</code>, <code>SoAd</code>), Fehler- und Diagnose-Handler (<code>Det</code>, <code>Dem</code>), Zeitbasis (<code>StbM</code>), RTE und OS zu.</li>\n<li>Zyklische Includes sind ausgeschlossen; die Speichereinteilung erfolgt über mehrfache Einbindung von <code>MemMap.h</code> in Source- und Header-Dateien gemäß AUTOSAR-Memory-Mapping-Konzept.</li>\n</ul>"}, {"id": "FIG-9794f5f403d4b2b0", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Include-Abhängigkeitsdiagramm zur Darstellung der Datei- und Header-Struktur des AUTOSAR Classic BSW-Moduls XCP. Es modelliert die statischen Inklusionsbeziehungen (<code>includes</code>) zwischen den C-Quelldateien (<code>Xcp.c</code>), den modulspezifischen Headerdateien (<code>Xcp.h</code>, <code>SchM_Xcp.h</code>, busspezifischen Transport- und Callback-Headern) sowie Schnittstellenheadern benachbarter Basissoftware-Module, des Betriebssystems und allgemeiner Typdefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Quell- und Header-Dateien des Moduls:</p>\n<ul class=\"fig-list\">\n<li><code>Xcp.c</code> (Quelldatei, mehrfach geschichtet dargestellt zur Repräsentation mehrerer Übersetzungseinheiten bzw. Instanzen)</li>\n<li><code>Xcp.h</code> (Haupt-Header des XCP-Moduls)</li>\n<li><code>SchM_Xcp.h</code> (Schedule Manager Header für XCP)</li>\n<li>Modulspezifische Transport-Layer- und Callback-Header: <code>XcpOnCan.h</code>, <code>XcpOnCan_Cbk.h</code>, <code>XcpOnEth.h</code>, <code>XcpOnEth_Cbk.h</code>, <code>XcpOnFr.h</code>, <code>XcpOnFr_Cbk.h</code></li>\n</ul>\n<p class=\"fig-p\">Integrierte BSW-, System- und Schnittstellen-Header:</p>\n<ul class=\"fig-list\">\n<li><code>CanIf.h</code> (CAN Interface)</li>\n<li><code>FrIf.h</code> (FlexRay Interface)</li>\n<li><code>SoAd.h</code> (Socket Adapter)</li>\n<li><code>Dem.h</code> (Diagnostic Event Manager)</li>\n<li><code>DemIntErrId.h</code> (Dem Internal Error IDs, eingebunden durch <code>Dem.h</code>)</li>\n<li><code>Det.h</code> (Default Error Tracer)</li>\n<li><code>RTE.h</code> (Runtime Environment Header)</li>\n<li><code>StbM.h</code> (Synchronized Time-Base Manager)</li>\n<li><code>Cpu.h</code> (Hardware-/CPU-spezifische Typen)</li>\n<li><code>Os.h</code> (Betriebssystem)</li>\n<li><code>MemMap.h</code> (Speicher-Mapping-Header, separat referenziert durch <code>Xcp.c</code> und <code>Xcp.h</code>)</li>\n<li><code>ComStack_Types.h</code> (Kommunikationsstapel-Basisdatentypen)</li>\n<li><code>Std_Types.h</code> (AUTOSAR Standarddatentypen, eingebunden über <code>ComStack_Types.h</code>)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenbeziehungen (gerichtete Pfeile mit der Semantik <code>includes</code>):</p>\n<ul class=\"fig-list\">\n<li><code>Xcp.c</code> bindet ein: <code>Xcp.h</code>, <code>SchM_Xcp.h</code>, <code>CanIf.h</code>, <code>FrIf.h</code>, <code>SoAd.h</code>, <code>Dem.h</code>, <code>Det.h</code>, <code>RTE.h</code>, <code>StbM.h</code>, <code>Cpu.h</code>, <code>Os.h</code>, <code>MemMap.h</code>.</li>\n<li><code>Xcp.h</code> bindet ein: <code>ComStack_Types.h</code>, <code>MemMap.h</code>, <code>XcpOnCan.h</code>, <code>XcpOnCan_Cbk.h</code>, <code>XcpOnEth.h</code>, <code>XcpOnEth_Cbk.h</code>, <code>XcpOnFr.h</code>, <code>XcpOnFr_Cbk.h</code>.</li>\n<li><code>Dem.h</code> bindet ein: <code>DemIntErrId.h</code>.</li>\n<li><code>ComStack_Types.h</code> bindet ein: <code>Std_Types.h</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert statische Kompilierzeit- und Präprozessor-Abhängigkeiten. Es beschreibt keinen dynamischen Kontrollfluss oder Laufzeitsequenzen, sondern definiert die transitiven und direkten Sichtbarkeiten von Typen, Makros, API-Deklarationen und Speicherkonfigurationen während des Übersetzungsvorgangs.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die Modulstruktur und <code>#include</code>-Hierarchie der XCP-Implementierung in AUTOSAR Classic:</p>\n<ul class=\"fig-list\">\n<li><code>Xcp.h</code> exportiert die Modulschnittstelle und stellt alle transportspezifischen Definitionen (<code>XcpOnCan<em>.h</code>, <code>XcpOnEth</em>.h</code>, <code>XcpOnFr*.h</code>) sowie <code>ComStack_Types.h</code> (und transitiv <code>Std_Types.h</code>) bereit.</li>\n<li><code>Xcp.c</code> realisiert die eigentliche Modulfunktionalität und greift direkt auf die Schnittstellen der Bus-Interfaces (<code>CanIf</code>, <code>FrIf</code>, <code>SoAd</code>), Fehler- und Diagnose-Handler (<code>Det</code>, <code>Dem</code>), Zeitbasis (<code>StbM</code>), RTE und OS zu.</li>\n<li>Zyklische Includes sind ausgeschlossen; die Speichereinteilung erfolgt über mehrfache Einbindung von <code>MemMap.h</code> in Source- und Header-Dateien gemäß AUTOSAR-Memory-Mapping-Konzept.</li>\n</ul>"}, {"id": "FIG-8153e075d7d63f3b", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Include-Abhängigkeitsdiagramm zur Darstellung der Datei- und Header-Struktur des AUTOSAR Classic BSW-Moduls XCP. Es modelliert die statischen Inklusionsbeziehungen (<code>includes</code>) zwischen den C-Quelldateien (<code>Xcp.c</code>), den modulspezifischen Headerdateien (<code>Xcp.h</code>, <code>SchM_Xcp.h</code>, busspezifischen Transport- und Callback-Headern) sowie Schnittstellenheadern benachbarter Basissoftware-Module, des Betriebssystems und allgemeiner Typdefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Quell- und Header-Dateien des Moduls:</p>\n<ul class=\"fig-list\">\n<li><code>Xcp.c</code> (Quelldatei, mehrfach geschichtet dargestellt zur Repräsentation mehrerer Übersetzungseinheiten bzw. Instanzen)</li>\n<li><code>Xcp.h</code> (Haupt-Header des XCP-Moduls)</li>\n<li><code>SchM_Xcp.h</code> (Schedule Manager Header für XCP)</li>\n<li>Modulspezifische Transport-Layer- und Callback-Header: <code>XcpOnCan.h</code>, <code>XcpOnCan_Cbk.h</code>, <code>XcpOnEth.h</code>, <code>XcpOnEth_Cbk.h</code>, <code>XcpOnFr.h</code>, <code>XcpOnFr_Cbk.h</code></li>\n</ul>\n<p class=\"fig-p\">Integrierte BSW-, System- und Schnittstellen-Header:</p>\n<ul class=\"fig-list\">\n<li><code>CanIf.h</code> (CAN Interface)</li>\n<li><code>FrIf.h</code> (FlexRay Interface)</li>\n<li><code>SoAd.h</code> (Socket Adapter)</li>\n<li><code>Det.h</code> (Default Error Tracer)</li>\n<li><code>RTE.h</code> (Runtime Environment Header)</li>\n<li><code>StbM.h</code> (Synchronized Time-Base Manager)</li>\n<li><code>Cpu.h</code> (Hardware-/CPU-spezifische Typen)</li>\n<li><code>Os.h</code> (Betriebssystem)</li>\n<li><code>MemMap.h</code> (Speicher-Mapping-Header, separat referenziert durch <code>Xcp.c</code> und <code>Xcp.h</code>)</li>\n<li><code>ComStack_Types.h</code> (Kommunikationsstapel-Basisdatentypen)</li>\n<li><code>Std_Types.h</code> (AUTOSAR Standarddatentypen, eingebunden über <code>ComStack_Types.h</code>)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenbeziehungen (gerichtete Pfeile mit der Semantik <code>includes</code>):</p>\n<ul class=\"fig-list\">\n<li><code>Xcp.c</code> bindet ein: <code>Xcp.h</code>, <code>SchM_Xcp.h</code>, <code>CanIf.h</code>, <code>FrIf.h</code>, <code>SoAd.h</code>, <code>Det.h</code>, <code>RTE.h</code>, <code>StbM.h</code>, <code>Cpu.h</code>, <code>Os.h</code>, <code>MemMap.h</code>.</li>\n<li><code>Xcp.h</code> bindet ein: <code>ComStack_Types.h</code>, <code>MemMap.h</code>, <code>XcpOnCan.h</code>, <code>XcpOnCan_Cbk.h</code>, <code>XcpOnEth.h</code>, <code>XcpOnEth_Cbk.h</code>, <code>XcpOnFr.h</code>, <code>XcpOnFr_Cbk.h</code>.</li>\n<li><code>ComStack_Types.h</code> bindet ein: <code>Std_Types.h</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert statische Kompilierzeit- und Präprozessor-Abhängigkeiten. Es beschreibt keinen dynamischen Kontrollfluss oder Laufzeitsequenzen, sondern definiert die transitiven und direkten Sichtbarkeiten von Typen, Makros, API-Deklarationen und Speicherkonfigurationen während des Übersetzungsvorgangs.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die Modulstruktur und <code>#include</code>-Hierarchie der XCP-Implementierung in AUTOSAR Classic:</p>\n<ul class=\"fig-list\">\n<li><code>Xcp.h</code> exportiert die Modulschnittstelle und stellt alle transportspezifischen Definitionen (<code>XcpOnCan<em>.h</code>, <code>XcpOnEth</em>.h</code>, <code>XcpOnFr*.h</code>) sowie <code>ComStack_Types.h</code> (und transitiv <code>Std_Types.h</code>) bereit.</li>\n<li><code>Xcp.c</code> realisiert die eigentliche Modulfunktionalität und greift direkt auf die Schnittstellen der Bus-Interfaces (<code>CanIf</code>, <code>FrIf</code>, <code>SoAd</code>), Fehler- und Status-Handler (<code>Det</code>), Zeitbasis (<code>StbM</code>), RTE und OS zu. Direkte Abhängigkeiten zu Dem-Headern bestehen für <code>Xcp.c</code> nicht.</li>\n<li>Zyklische Includes sind ausgeschlossen; die Speichereinteilung erfolgt über mehrfache Einbindung von <code>MemMap.h</code> in Source- und Header-Dateien gemäß AUTOSAR-Memory-Mapping-Konzept.</li>\n</ul>"}], "trans": [{"from": "FIG-5968492c82422fcc", "to": "FIG-9794f5f403d4b2b0", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9794f5f403d4b2b0", "to": "FIG-8153e075d7d63f3b", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Header Dem.h und DemIntErrId.h einschließlich der Inklusionsbeziehungen (<code>Xcp.c</code> -> <code>Dem.h</code>, <code>Dem.h</code> -> <code>DemIntErrId.h</code>) entfernt.</li>\n</ul>"}]};
